package com.medibook.service;
import com.medibook.dto.DoctorDtos.AvailabilityInput;import com.medibook.entity.*;import com.medibook.repository.*;import org.junit.jupiter.api.Test;import org.springframework.web.server.ResponseStatusException;import java.time.*;import java.math.BigDecimal;import java.util.Optional;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;
class DoctorServiceTest {
 @Test void doctorSearchBuildsCriteriaWithoutBindingNullFilterParameters(){DoctorProfileRepository doctors=mock(DoctorProfileRepository.class);when(doctors.findAll(org.mockito.ArgumentMatchers.<org.springframework.data.jpa.domain.Specification<DoctorProfile>>any())).thenReturn(java.util.List.of());DoctorService service=new DoctorService(doctors,mock(UserRepository.class),mock(SpecialtyRepository.class),mock(AvailabilityRepository.class),mock(AppointmentRepository.class),"Asia/Kolkata");assertTrue(service.search(null,null,null).isEmpty());verify(doctors).findAll(org.mockito.ArgumentMatchers.<org.springframework.data.jpa.domain.Specification<DoctorProfile>>any());}

 @Test void rejectsOverlappingWorkingPeriods(){DoctorProfileRepository doctors=mock(DoctorProfileRepository.class);AvailabilityRepository availability=mock(AvailabilityRepository.class);AppointmentRepository appointments=mock(AppointmentRepository.class);when(doctors.lockById(5L)).thenReturn(Optional.of(mock(DoctorProfile.class)));DoctorService service=new DoctorService(doctors,mock(UserRepository.class),mock(SpecialtyRepository.class),availability,appointments,"Asia/Kolkata");var input=java.util.List.of(new AvailabilityInput(DayOfWeek.MONDAY,LocalTime.of(9,0),LocalTime.of(12,0),30,null,null),new AvailabilityInput(DayOfWeek.MONDAY,LocalTime.of(11,30),LocalTime.of(14,0),30,null,null));ResponseStatusException error=assertThrows(ResponseStatusException.class,()->service.setAvailability(5L,input));assertEquals(409,error.getStatusCode().value());verify(availability,never()).deleteByDoctorId(5L);}

 @Test void emptyAvailabilityClearsWorkingPeriods(){DoctorProfileRepository doctors=mock(DoctorProfileRepository.class);AvailabilityRepository availability=mock(AvailabilityRepository.class);AppointmentRepository appointments=mock(AppointmentRepository.class);when(doctors.lockById(5L)).thenReturn(Optional.of(mock(DoctorProfile.class)));when(appointments.findByDoctorIdOrderByStartAtAsc(5L)).thenReturn(java.util.List.of());DoctorService service=new DoctorService(doctors,mock(UserRepository.class),mock(SpecialtyRepository.class),availability,appointments,"Asia/Kolkata");assertTrue(service.setAvailability(5L,java.util.List.of()).isEmpty());verify(availability).deleteByDoctorId(5L);verify(availability).saveAll(java.util.List.of());}

 @Test void updatingProfileDoesNotReactivateAnAdminDisabledDoctor(){DoctorProfileRepository doctors=mock(DoctorProfileRepository.class);UserRepository users=mock(UserRepository.class);SpecialtyRepository specialties=mock(SpecialtyRepository.class);DoctorProfile profile=mock(DoctorProfile.class);AppUser user=mock(AppUser.class);Specialty specialty=mock(Specialty.class);when(doctors.findById(5L)).thenReturn(Optional.of(profile));when(doctors.save(profile)).thenReturn(profile);when(profile.getUser()).thenReturn(user);when(profile.getUserId()).thenReturn(5L);when(specialties.findByNameIgnoreCase("Cardiology")).thenReturn(Optional.of(specialty));DoctorService service=new DoctorService(doctors,users,specialties,mock(AvailabilityRepository.class),mock(AppointmentRepository.class),"Asia/Kolkata");service.updateProfile(5L,new com.medibook.dto.DoctorDtos.ProfileUpdate("Dr. Test","Cardiology","MBBS",3,BigDecimal.TEN,"City","Bio",false));verify(user,never()).setActive(true);}
}
